"use client";

import { useState, useRef } from "react";
import { cn } from "@/lib/utils";
import { X, Check } from "lucide-react";

interface SimpleInputProps {
  label?: string;
  placeholder?: string;
  error?: string;
  success?: string;
  onChange?: (value: string) => void;
  onClear?: () => void;
  type?: "text" | "email" | "password" | "search";
}

export default function Input_01({
  label = "Label",
  placeholder = "Type something...",
  error,
  success,
  onChange,
  onClear,
  type = "text",
}: SimpleInputProps) {
  const [value, setValue] = useState("");
  const [isFocused, setIsFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleClear = () => {
    setValue("");
    onClear?.();
    inputRef.current?.focus();
  };

  return (
    <div className="w-full max-w-xs space-y-2">
      <label
        htmlFor={label}
        className="text-xs font-medium text-zinc-300"
      >
        {label}
      </label>

      <div className="relative">
        <input
          ref={inputRef}
          id={label}
          type={type}
          value={value}
          onChange={(e) => {
            setValue(e.target.value);
            onChange?.(e.target.value);
          }}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          placeholder={placeholder}
          className={cn(
            "h-11 w-full rounded-xl border px-3.5 pr-10",
            "bg-white/[0.025] backdrop-blur-xl",
            "text-sm text-white",
            "placeholder:text-zinc-600",
            "transition-all duration-200",
            "focus:outline-none",
            error
              ? "border-red-400/40 focus:border-red-400/60 focus:ring-2 focus:ring-red-400/10"
              : success
                ? "border-emerald-400/40 focus:border-emerald-400/60 focus:ring-2 focus:ring-emerald-400/10"
                : cn(
                    "border-white/[0.08]",
                    "hover:border-white/[0.12]",
                    "focus:border-violet-400/50",
                    "focus:ring-2 focus:ring-violet-500/10",
                  ),
            isFocused && !error && !success && "bg-white/[0.035]",
          )}
        />

        {value && (
          <button
            type="button"
            onClick={handleClear}
            aria-label="Clear input"
            className={cn(
              "absolute right-2.5 top-1/2 -translate-y-1/2",
              "flex h-7 w-7 items-center justify-center rounded-lg",
              "text-zinc-600 transition-colors",
              "hover:bg-white/[0.06] hover:text-zinc-300",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-500/30",
            )}
          >
            <X className="h-3.5 w-3.5" />
          </button>
        )}

        <div
          className={cn(
            "absolute -right-5 top-1/2 -translate-y-1/2",
            "transition-opacity duration-200",
            !error && !success && "opacity-0",
          )}
        >
          {error ? (
            <X className="h-4 w-4 text-red-400" />
          ) : success ? (
            <Check className="h-4 w-4 text-emerald-400" />
          ) : null}
        </div>
      </div>

      {(error || success) && (
        <p
          className={cn(
            "text-xs",
            error ? "text-red-400" : "text-emerald-400",
          )}
        >
          {error || success}
        </p>
      )}
    </div>
  );
}

"use client";

import { useState, useRef, type RefObject } from "react";
import { cn } from "@/lib/utils";
import { X, Check, Plus, Tag as TagIcon } from "lucide-react";
import { useTags } from "@/hooks/use-tags";
import { useClickOutside } from "@/hooks/use-click-outside";

interface Tag {
  id: string;
  label: string;
  color?: string;
}

interface TagInputProps {
  onChange?: (tags: Tag[]) => void;
  defaultTags?: Tag[];
  suggestions?: Tag[];
  maxTags?: number;
  label?: string;
  placeholder?: string;
  error?: string;
}

const defaultKokonutTag: Tag = {
  id: "kokonut-ui",
  label: "codesnippetui",
};

const tagStyles = {
  base: "inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-xs font-medium transition-all duration-200",
  colors: {
    blue: "border-violet-400/15 bg-violet-400/[0.08] text-violet-300 hover:border-violet-400/25",
    purple: "border-violet-400/15 bg-violet-400/[0.08] text-violet-300 hover:border-violet-400/25",
    green: "border-emerald-400/15 bg-emerald-400/[0.06] text-emerald-300 hover:border-emerald-400/25",
  },
};

export default function Input_02({
  onChange,
  defaultTags = [defaultKokonutTag],
  suggestions = [
    { id: "nextjs", label: "Next.js" },
    { id: "react", label: "React" },
    { id: "tailwind", label: "Tailwind" },
  ],
  maxTags = 10,
  label = "Tags",
  placeholder = "Add tags...",
  error,
}: TagInputProps) {
  const { tags, addTag, removeTag, removeLastTag } = useTags({
    onChange,
    defaultTags,
    maxTags,
  });

  const [input, setInput] = useState("");
  const [isOpen, setIsOpen] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);

  const inputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const filteredSuggestions = suggestions
    .filter(
      (suggestion) =>
        suggestion.label.toLowerCase().includes(input.toLowerCase()) &&
        !tags.find((tag) => tag.id === suggestion.id),
    )
    .slice(0, 5);

  const canAddNewTag =
    !suggestions.find(
      (s) => s.label.toLowerCase() === input.toLowerCase(),
    ) && input.length > 0;

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Backspace" && input === "" && tags.length > 0) {
      removeLastTag();
    } else if (e.key === "Enter" && input) {
      e.preventDefault();

      if (isOpen && filteredSuggestions[selectedIndex]) {
        addTag(filteredSuggestions[selectedIndex]);
        setInput("");
        setIsOpen(false);
      } else if (canAddNewTag) {
        addTag({ id: input, label: input });
        setInput("");
        setIsOpen(false);
      }
    } else if (e.key === "Escape") {
      setIsOpen(false);
    }
  }

  useClickOutside(
    containerRef as RefObject<HTMLElement>,
    () => setIsOpen(false),
  );

  return (
    <div
      ref={containerRef}
      className="w-full max-w-full space-y-2 sm:max-w-2xl"
    >
      {label && (
        <label
          className="text-xs font-medium text-zinc-300"
          htmlFor={label}
        >
          {label}
        </label>
      )}

      <div
        className={cn(
          "relative flex min-h-11 flex-row flex-wrap items-center gap-1.5",
          "rounded-xl border p-2",
          "border-white/[0.08]",
          "bg-white/[0.025]",
          "backdrop-blur-xl",
          "transition-all duration-200",
          "hover:border-white/[0.12]",
          "focus-within:border-violet-400/50",
          "focus-within:ring-2 focus-within:ring-violet-500/10",
        )}
      >
        {tags.map((tag) => (
          <span
            key={tag.id}
            className={cn(
              tagStyles.base,
              tag.color || tagStyles.colors.blue,
            )}
          >
            {tag.label}

            <button
              type="button"
              onClick={() => removeTag(tag.id)}
              aria-label={`Remove ${tag.label}`}
              className="rounded-full p-0.5 text-current/50 transition-colors hover:bg-white/[0.08] hover:text-current"
            >
              <X className="h-3 w-3" />
            </button>
          </span>
        ))}

        <input
          ref={inputRef}
          type="text"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setIsOpen(true);
            setSelectedIndex(0);
          }}
          onFocus={() => setIsOpen(true)}
          onKeyDown={handleKeyDown}
          placeholder={tags.length === 0 ? placeholder : ""}
          className={cn(
            "h-7 min-w-[120px] flex-1 bg-transparent px-1",
            "text-sm text-white",
            "placeholder:text-zinc-600",
            "focus:outline-none",
          )}
        />

        {isOpen && (input || filteredSuggestions.length > 0) && (
          <div
            className={cn(
              "absolute left-0 right-0 top-full z-50 mt-2",
              "max-h-[300px] overflow-y-auto",
              "rounded-xl border border-white/[0.08]",
              "bg-[#0c0c0f]/95 backdrop-blur-xl",
              "shadow-[0_15px_50px_rgba(0,0,0,0.45)]",
            )}
          >
            <div className="border-b border-white/[0.06] px-3 py-2.5">
              <span className="text-[10px] font-medium uppercase tracking-[0.14em] text-zinc-600">
                Choose or create
              </span>
            </div>

            <div className="flex flex-wrap gap-1.5 p-2">
              {filteredSuggestions.map((suggestion, index) => (
                <button
                  type="button"
                  key={suggestion.id}
                  onClick={() => {
                    addTag(suggestion);
                    setInput("");
                    setIsOpen(false);
                  }}
                  className={cn(
                    tagStyles.base,
                    selectedIndex === index
                      ? tagStyles.colors.blue
                      : "border-white/[0.07] bg-white/[0.025] text-zinc-400 hover:border-white/[0.12] hover:text-zinc-200",
                  )}
                >
                  {suggestion.label}

                  {selectedIndex === index && (
                    <Check className="h-3 w-3" />
                  )}
                </button>
              ))}

              {canAddNewTag && (
                <button
                  type="button"
                  onClick={() => {
                    addTag({
                      id: input,
                      label: input,
                      color: tagStyles.colors.blue,
                    });
                    setInput("");
                    setIsOpen(false);
                  }}
                  className={cn(
                    tagStyles.base,
                    "border-violet-400/15 bg-violet-400/[0.06] text-violet-300 hover:bg-violet-400/[0.1]",
                  )}
                >
                  <Plus className="h-3 w-3" />
                  Create "{input}"
                </button>
              )}

              {!filteredSuggestions.length && !canAddNewTag && (
                <div className="flex w-full items-center gap-2 px-2 py-3 text-xs text-zinc-600">
                  <TagIcon className="h-3.5 w-3.5" />
                  No matching tags
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {error && <p className="text-xs text-red-400">{error}</p>}
    </div>
  );
}

"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";
import { Upload, X, FileText, CheckCircle2 } from "lucide-react";
import { useFileInput } from "@/hooks/use-file-input";

export default function Input_03() {
  const [isDragging, setIsDragging] = useState(false);
  const [preview, setPreview] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);

  const {
    fileName,
    fileInputRef,
    clearFile,
    error,
    validateAndSetFile,
    fileSize,
  } = useFileInput({
    accept: "image/*",
    maxSize: 5,
  });

  function handleFile(file: File) {
    validateAndSetFile(file);
    simulateUpload(file);
  }

  function simulateUpload(file: File) {
    let progress = 0;

    const interval = setInterval(() => {
      progress += 10;
      setUploadProgress(progress);

      if (progress >= 100) {
        clearInterval(interval);

        if (file.type.startsWith("image/")) {
          const reader = new FileReader();

          reader.onloadend = () => {
            setPreview(reader.result as string);
          };

          reader.readAsDataURL(file);
        }
      }
    }, 100);
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    setIsDragging(false);

    const droppedFile = e.dataTransfer.files[0];
    if (!droppedFile) return;

    handleFile(droppedFile);
  }

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    handleFile(selectedFile);
  }

  function removeFile() {
    clearFile();
    setPreview(null);
    setUploadProgress(0);
  }

  return (
    <div className="w-full max-w-md space-y-2">
      <label className="text-xs font-medium text-zinc-300">
        Upload file
      </label>

      <div
        role="button"
        tabIndex={0}
        onDragOver={(e) => {
          e.preventDefault();
          setIsDragging(true);
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            fileInputRef.current?.click();
          }
        }}
        aria-label="Upload file"
        className={cn(
          "group relative cursor-pointer overflow-hidden",
          "rounded-2xl border border-dashed",
          "backdrop-blur-xl",
          "transition-all duration-300",
          isDragging
            ? "border-violet-400/50 bg-violet-400/[0.06]"
            : "border-white/[0.10] bg-white/[0.02] hover:border-violet-400/30 hover:bg-white/[0.035]",
        )}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleChange}
          className="hidden"
        />

        <div className="p-7">
          {!fileName ? (
            <div className="flex flex-col items-center gap-3 text-center">
              <div
                className={cn(
                  "flex h-12 w-12 items-center justify-center rounded-2xl",
                  "border border-white/[0.08] bg-white/[0.035]",
                  "transition-all duration-300",
                  "group-hover:border-violet-400/20 group-hover:bg-violet-400/[0.06]",
                )}
              >
                <Upload className="h-5 w-5 text-zinc-500 group-hover:text-violet-300" />
              </div>

              <div>
                <p className="text-sm font-medium text-zinc-300">
                  Drop your file here
                </p>
                <p className="mt-1 text-xs text-zinc-600">
                  or click to browse · Max 5 MB
                </p>
              </div>
            </div>
          ) : (
            <div className="flex items-center gap-3">
              {preview ? (
                <div className="h-14 w-14 shrink-0 overflow-hidden rounded-xl border border-white/[0.08]">
                  <img
                    src={preview}
                    alt="Preview"
                    className="h-full w-full object-cover"
                  />
                </div>
              ) : (
                <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-xl border border-white/[0.08] bg-white/[0.035]">
                  <FileText className="h-5 w-5 text-zinc-500" />
                </div>
              )}

              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-zinc-200">
                  {fileName}
                </p>

                <p className="mt-0.5 text-xs text-zinc-600">
                  {fileSize
                    ? `${(fileSize / 1024 / 1024).toFixed(2)} MB`
                    : "0 MB"}
                </p>

                {uploadProgress < 100 ? (
                  <div className="mt-2 h-1 overflow-hidden rounded-full bg-white/[0.07]">
                    <div
                      className="h-full rounded-full bg-violet-400 transition-all duration-200"
                      style={{ width: `${uploadProgress}%` }}
                    />
                  </div>
                ) : (
                  <div className="mt-1.5 flex items-center gap-1 text-[10px] text-emerald-400">
                    <CheckCircle2 className="h-3 w-3" />
                    Ready
                  </div>
                )}
              </div>

              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  removeFile();
                }}
                aria-label="Remove file"
                className={cn(
                  "flex h-8 w-8 shrink-0 items-center justify-center rounded-lg",
                  "text-zinc-600 transition-colors",
                  "hover:bg-white/[0.06] hover:text-zinc-300",
                )}
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          )}
        </div>
      </div>

      {error && <p className="text-xs text-red-400">{error}</p>}
    </div>
  );
}

"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";

interface NumericInputProps {
  min?: number;
  max?: number;
  step?: number;
  defaultValue?: number;
}

export default function Input_04({
  min = 0,
  max = 100,
  step = 1,
  defaultValue = 50,
}: NumericInputProps) {
  const [value, setValue] = useState(defaultValue);
  const [isFocused, setIsFocused] = useState(false);

  const percentage =
    max === min ? 0 : ((value - min) / (max - min)) * 100;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = Number.parseFloat(e.target.value);

    if (
      !Number.isNaN(newValue) &&
      newValue >= min &&
      newValue <= max
    ) {
      setValue(newValue);
    }
  };

  const incrementValue = () => {
    setValue(Math.min(value + step, max));
  };

  const decrementValue = () => {
    setValue(Math.max(value - step, min));
  };

  return (
    <div className="w-full max-w-xs">
      <div
        className={cn(
          "flex h-11 items-center overflow-hidden rounded-xl border",
          "bg-white/[0.025] backdrop-blur-xl",
          "transition-all duration-200",
          isFocused
            ? "border-violet-400/50 ring-2 ring-violet-500/10"
            : "border-white/[0.08] hover:border-white/[0.12]",
        )}
      >
        <button
          type="button"
          onClick={decrementValue}
          disabled={value <= min}
          aria-label="Decrement value"
          className={cn(
            "flex h-full w-11 items-center justify-center",
            "border-r border-white/[0.06]",
            "text-lg text-zinc-500 transition-colors",
            "hover:bg-white/[0.05] hover:text-zinc-200",
            "disabled:cursor-not-allowed disabled:opacity-30",
          )}
        >
          −
        </button>

        <input
          type="number"
          value={value}
          onChange={handleChange}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          min={min}
          max={max}
          step={step}
          className={cn(
            "w-full bg-transparent text-center",
            "text-sm font-medium text-white",
            "focus:outline-none",
            "[-moz-appearance:textfield]",
            "[&::-webkit-inner-spin-button]:appearance-none",
            "[&::-webkit-outer-spin-button]:appearance-none",
          )}
        />

        <button
          type="button"
          onClick={incrementValue}
          disabled={value >= max}
          aria-label="Increment value"
          className={cn(
            "flex h-full w-11 items-center justify-center",
            "border-l border-white/[0.06]",
            "text-lg text-zinc-500 transition-colors",
            "hover:bg-white/[0.05] hover:text-zinc-200",
            "disabled:cursor-not-allowed disabled:opacity-30",
          )}
        >
          +
        </button>
      </div>

      <div className="mt-3 h-1 overflow-hidden rounded-full bg-white/[0.07]">
        <div
          className="h-full rounded-full bg-violet-400 transition-all duration-200"
          style={{ width: `${percentage}%` }}
        />
      </div>

      <div className="mt-1.5 flex justify-between text-[10px] text-zinc-600">
        <span>{min}</span>
        <span>{max}</span>
      </div>
    </div>
  );
}

