          <Image
            src={avatarUrls[i % avatarUrls.length]}
            width={72}
            height={72}
            alt={`Team member ${i + 1}`}
            className="h-16 w-16 rounded-full object-cover"
          />
        </div>
      </motion.div>
    ));
